<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; ?>
<div class="topbar"><h1>Orders</h1><div class="row"><?php foreach (['' => 'All', 'pending' => 'Pending', 'awaiting_payment' => 'Awaiting payment', 'paid' => 'Paid', 'processing' => 'Processing', 'completed' => 'Completed', 'failed' => 'Failed'] as $k => $l): ?><a class="btn btn-sm <?= $status === $k ? 'btn-dark' : 'btn-ghost' ?>" href="?status=<?= $k ?>"><?= $l ?></a><?php endforeach; ?></div></div>
<?php if (!$rows): ?><div class="empty">No orders.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Recurring</th><th>Status</th><th>Created</th><th>Paid</th></tr></thead><tbody>
<?php foreach ($rows as $o): ?><tr><td><a href="/admin/orders/<?= e($o['number']) ?>"><?= e($o['number']) ?></a></td><td class="small"><?= e($o['name']) ?><div class="muted"><?= e($o['email']) ?></div></td><td><?= money((int)$o['total_cents']) ?></td><td><?= money((int)$o['recurring_cents']) ?></td><td><?php $badge($o['status']); ?></td><td class="small"><?= e(substr($o['created_at'], 0, 16)) ?></td><td class="small"><?= e(substr((string)$o['paid_at'], 0, 16)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
